// Routing (spec Step 4) and escalation (spec Step 6): pure functions, no I/O.
// scripts/build-workflow.js inlines this file into an n8n Code node, so it must
// not use require/import or touch files or the network.

const QUEUE_BY_CATEGORY = {
  "Bug Report": "Engineering",
  "Incident/Outage": "Engineering",
  "Feature Request": "Product",
  "Billing Issue": "Billing",
  "Technical Question": "IT/Security",
};

const ESCALATION_QUEUE = "Escalation";
// Multi-user impact is an outage signal only on a problem report. On a feature request,
// billing issue or question it describes who is asking, not an incident.
const MULTI_USER_CATEGORIES = ["Bug Report", "Incident/Outage"];
const CONFIDENCE_THRESHOLD = 0.7; // escalate below this
const BILLING_DISCREPANCY_LIMIT = 500; // escalate when invoiced minus contract exceeds this

// Outage keywords, matched case-insensitively on the raw message. No "g" flag:
// a global regex keeps lastIndex between test() calls and would skip matches.
const OUTAGE_PATTERN = new RegExp(
  [
    /\boutages?\b/, // "outage(s)": the spec's own example
    /\b(?:is|are|was|were|went|been)\s+down\b/, // "the portal is down", "it went down"
    /\w['’]s\s+down\b/, // "it's down" / "it’s down": straight or curly apostrophe
    /(?<![\w-])down\s+for\b/, // "down for all users": the spec's other example; not "drop-down for"
  ]
    .map((part) => part.source)
    .join("|"),
  "i",
);

// Strict structured outputs should make bad output impossible, but a category
// outside the map or a confidence outside 0–1 is treated as an LLM failure
// rather than throwing, so the record is escalated instead of dropped.
function isUsable(llm) {
  const classification = llm?.classification;
  return (
    Object.hasOwn(QUEUE_BY_CATEGORY, classification?.category ?? "") &&
    typeof classification.confidence === "number" &&
    classification.confidence >= 0 &&
    classification.confidence <= 1
  );
}

// Invoiced minus contract, or null if either amount is missing. Works in whole
// cents: in floating point 600.20 − 100.20 is 500.00000000000006, which would
// fire the "> 500" rule on an exact $500 discrepancy.
function billingDiscrepancy(billing) {
  const invoiced = billing?.invoiced_amount;
  const contract = billing?.contract_amount;
  if (typeof invoiced !== "number" || typeof contract !== "number") return null;
  return (Math.round(invoiced * 100) - Math.round(contract * 100)) / 100;
}

// Reasons in the order schema.json lists them. Unusable LLM output contributes
// only llm_error; the keyword check still runs on the raw message.
function escalationReasons(llm, message) {
  const usable = isUsable(llm);
  const discrepancy = usable
    ? billingDiscrepancy(llm.enrichment?.billing)
    : null;
  const fired = {
    low_confidence:
      usable && llm.classification.confidence < CONFIDENCE_THRESHOLD,
    // The model's own confidence stays high on vague and off-topic messages, so the
    // low-confidence fallback also uses an extracted fact: is there anything to act on?
    not_actionable: usable && llm.enrichment?.actionable === false,
    outage_keyword: OUTAGE_PATTERN.test(message),
    multi_user_impact:
      usable &&
      llm.enrichment?.multi_user_impact === true &&
      MULTI_USER_CATEGORIES.includes(llm.classification.category),
    incident_category:
      usable && llm.classification.category === "Incident/Outage",
    billing_discrepancy_over_500:
      discrepancy !== null && discrepancy > BILLING_DISCREPANCY_LIMIT,
    llm_error: !usable,
  };
  return Object.keys(fired).filter((reason) => fired[reason]);
}

// llm is the $defs.llm object, or null when the call failed.
function route(llm, message) {
  const usable = isUsable(llm);
  const standardQueue = usable
    ? QUEUE_BY_CATEGORY[llm.classification.category]
    : null;
  const reasons = escalationReasons(llm, message);
  const flagged = reasons.length > 0;
  return {
    routing: {
      standard_queue: standardQueue,
      destination_queue: flagged ? ESCALATION_QUEUE : standardQueue,
    },
    escalation: {
      flagged,
      reasons,
      billing_discrepancy: usable
        ? billingDiscrepancy(llm.enrichment?.billing)
        : null,
    },
  };
}

if (typeof module !== "undefined") {
  module.exports = {
    QUEUE_BY_CATEGORY,
    CONFIDENCE_THRESHOLD,
    BILLING_DISCREPANCY_LIMIT,
    OUTAGE_PATTERN,
    billingDiscrepancy,
    escalationReasons,
    route,
  };
}

// ---- end of src/routing.js ----

// Record assembly: parses the model's reply and builds the output record in schema order. Pure
// functions, no I/O. scripts/build-workflow.js inlines this file after src/routing.js in the same
// n8n Code node, so it must not use require/import. route() comes in as an argument instead.

// A failed call, a refusal, a cut-off reply or content that isn't JSON all leave llm null, which
// route() turns into llm_error and the Escalation queue.
function parseReply(response) {
  if (response.error !== undefined) {
    const e = response.error;
    return {
      llm: null,
      error: "OpenAI call failed: " + (typeof e === "string" ? e : e.message ?? JSON.stringify(e)),
    };
  }
  const choice = response.choices?.[0];
  if (choice?.message?.refusal) return { llm: null, error: "Model refused: " + choice.message.refusal };
  if (choice?.finish_reason !== "stop") {
    return { llm: null, error: "Model reply cut off: finish_reason " + choice?.finish_reason };
  }
  try {
    return { llm: JSON.parse(choice.message.content), error: null };
  } catch (e) {
    return { llm: null, error: "Model reply is not JSON: " + e.message };
  }
}

// OpenAI's 401 message quotes part of the key; keep it out of the record.
function redactKey(text) {
  return text.replace(/sk-[\w*-]+/g, "[redacted key]");
}

// intake: { id, source, received_at, message } from Step 1. response: the OpenAI reply, or the
// HTTP node's error item. model: the requested model, used when the reply doesn't name one.
function buildRecord({ intake, response, route, model, processedAt }) {
  const { llm, error } = parseReply(response);
  const { routing, escalation } = route(llm, intake.message);
  const failed = escalation.reasons.includes("llm_error");
  const reason = failed
    ? error ?? "Model output outside the allowed categories or confidence range"
    : null;
  return {
    ...intake,
    classification: failed ? null : llm.classification,
    enrichment: failed ? null : llm.enrichment,
    routing,
    summary: failed ? null : llm.summary,
    escalation,
    meta: {
      model: response.model ?? model,
      processed_at: processedAt,
      error: reason && redactKey(reason),
    },
  };
}

if (typeof module !== "undefined") {
  module.exports = { parseReply, redactKey, buildRecord };
}

// ---- end of src/record.js ----

return [{ json: buildRecord({
  intake: $("Step 1 · Ingestion").first().json.record,
  response: $input.first().json,
  route,
  model: "gpt-4o-mini",
  processedAt: new Date().toISOString(),
}) }];

const record = $("Steps 4, 6 · Routing and escalation").first().json;
if ($("Step 1 · Ingestion").first().json.entry !== "form") return [{ json: record }];
const c = record.classification;
const fields = [
  "Category: " + (c?.category ?? "none (the LLM call failed)"),
  "Priority: " + (c?.priority ?? "none"),
  "Confidence: " + (c?.confidence ?? "none"),
  "Destination queue: " + record.routing.destination_queue,
  "Reasons: " + (record.escalation.reasons.join(", ") || "none"),
  "Summary: " + (record.summary ?? "none"),
];
return [{ json: { formSubmittedText: fields.join(" · ") } }];
